import{_ as t,K as l,a as s,c as o,ac as c,q as r,b as i,k as n}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"IM Server","description":"历史 IM 需求草稿：连接身份、好友与群权限、消息确认、离线补拉及待确认项。","frontmatter":{"title":"IM Server","description":"历史 IM 需求草稿：连接身份、好友与群权限、消息确认、离线补拉及待确认项。","sources":[{"repository":"jekyall_blog","file":"_posts/Dev/软件设计/IM Server.md"}],"showdocs":{"topics":[{"id":"architecture","title":"架构风格与模块边界","link":"/topics/architecture/"},{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"架构取舍与原文","scope":"historical","audience":"general","group":"原理与设计","summary":"历史 IM 需求草稿：连接身份、好友与群权限、消息确认、离线补拉及待确认项。","status":"active","related":[{"title":"istio 1.7","link":"/systems/kubernetes/plus/subjects/istio-1.7","kind":"知识专题","scope":"historical","audience":"general"},{"title":"库存服务的端口与适配器实践","link":"/principles/distributed-architecture/architecture/cases/application","kind":"库存边界实践","scope":"general","audience":"general"},{"title":"模块边界、数据所有权与架构决策","link":"/principles/distributed-architecture/architecture/module-boundaries","kind":"模块与交互决策","scope":"general","audience":"general"},{"title":"时序图示例","link":"/principles/distributed-architecture/architecture/cases/sequence-diagram","kind":"架构取舍与原文","scope":"general","audience":"general"},{"title":"办公系统需求草稿","link":"/principles/distributed-architecture/architecture/cases/%E5%8A%9E%E5%85%AC%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E7%A8%BF","kind":"架构取舍与原文","scope":"historical","audience":"general"}],"prev":{"text":"时序图示例","link":"/principles/distributed-architecture/architecture/cases/sequence-diagram"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"时序图示例","link":"/principles/distributed-architecture/architecture/cases/sequence-diagram"},"next":false},"headers":[],"relativePath":"principles/distributed-architecture/architecture/cases/im-server.md","filePath":"principles/distributed-architecture/architecture/cases/im-server.md"}'),u={name:"principles/distributed-architecture/architecture/cases/im-server.md"};function d(h,e,p,m,g,I){const a=l("Mermaid");return s(),o("div",null,[e[0]||(e[0]=c('<h1 id="im-server" tabindex="-1">IM Server <a class="header-anchor" href="#im-server" aria-label="Permalink to &quot;IM Server&quot;">​</a></h1><p>这是一份历史 IM 技术候选与需求草稿，不代表现网已实现以下服务或规则。先区分连接路由与账号身份，再看好友/群权限、<a href="#消息确认需要区分三个阶段">消息确认</a>及<a href="#离线补拉与重投递">断线补拉</a>；原稿语义不明和租约时长冲突列为待确认，不补猜产品约定。</p><h2 id="go-im" tabindex="-1">Go IM <a class="header-anchor" href="#go-im" aria-label="Permalink to &quot;Go IM&quot;">​</a></h2><h3 id="实现技术" tabindex="-1">实现技术 <a class="header-anchor" href="#实现技术" aria-label="Permalink to &quot;实现技术&quot;">​</a></h3><ul><li>Go(WebSocket)</li><li>mysql</li><li>MQ</li><li>Redis</li><li>mongodb</li></ul><h3 id="实现思路" tabindex="-1">实现思路 <a class="header-anchor" href="#实现思路" aria-label="Permalink to &quot;实现思路&quot;">​</a></h3><h3 id="身份与连接" tabindex="-1">身份与连接 <a class="header-anchor" href="#身份与连接" aria-label="Permalink to &quot;身份与连接&quot;">​</a></h3><ul><li>客户端通过 HTTP Upgrade 建立 WebSocket；成功升级的状态码为 101。连接标识用于路由，不能替代认证身份。</li><li>原稿设想首次连接提交用户名、可选群组名并取得 token；认证、注册、入群应各自校验。重连必须验证凭据，不能仅凭客户端自报用户名恢复身份。</li><li><strong>待确认 IM-01</strong>：原句“需要在公共的搜索页面添加好友才能卸载对聊名字”语义不明。需产品拥有者明确添加好友后究竟开放什么信息或会话能力。</li></ul><h3 id="好友与群权限" tabindex="-1">好友与群权限 <a class="header-anchor" href="#好友与群权限" aria-label="Permalink to &quot;好友与群权限&quot;">​</a></h3><ul><li>历史好友流程为搜索用户名、发送申请、对端响应；<strong>待确认 IM-02</strong>：原句“接受或者同故意”未明确拒绝、同意或其他状态，需确认申请状态和双方列表更新规则。</li><li>原稿设想一方删除好友后双方列表移除对方，尚需确认是否同时禁止私聊及历史读取；不能把“删除好友”理解成删除账号。</li><li>原稿设想分享群号入群、退群后停止接收消息，由创建者解散群或移出成员。服务端仍须验证操作者权限、成员资格及群状态；历史消息可见范围需产品另定。</li><li>文件与音频先上传，再将资源引用发送到会话；下载时仍应按当前身份和会话权限授权，不能把持有 URL 当作可读取证明。</li></ul><h3 id="在线租约与离线补拉" tabindex="-1">在线租约与离线补拉 <a class="header-anchor" href="#在线租约与离线补拉" aria-label="Permalink to &quot;在线租约与离线补拉&quot;">​</a></h3><ul><li>原稿计划在 Redis 记录在线会话；<strong>待确认 IM-03</strong>：有效期原文同时出现“两小时”与“3小时”，不能直接选为 TTL。需确认租约时长、心跳续约、断线和多设备规则。</li><li>在线状态只用于选择推送策略，不保证此刻可达。发送时先校验身份与会话权限，再按消息 ID 去重并持久保存；确认阶段见下文。</li><li>消息队列驱动投递，不作为用户已收到的唯一证据。断线后按持久会话游标补拉并去重，不能只消费在线时对应的一次队列任务。</li></ul><h2 id="消息确认需要区分三个阶段" tabindex="-1">消息确认需要区分三个阶段 <a class="header-anchor" href="#消息确认需要区分三个阶段" aria-label="Permalink to &quot;消息确认需要区分三个阶段&quot;">​</a></h2><p>原稿是技术候选与需求记录，下面是补充设计推演，不确认这些存储均已部署。WebSocket连接标识用于路由，账号身份必须由认证流程确认；连接断开重建时不能仅凭客户端自报用户名恢复身份。在线状态通常用会话租约与心跳表达，租约有效也不证明此刻推送一定成功。</p><p>发送消息时，先验证会话身份及好友或群成员权限，再按客户端消息标识去重并保存消息。服务端已接收、对端已收到、用户已读是三个不同确认：只有持久化确认才能支持断线补拉，读回执则是额外业务事件。群成员退出后，实时推送与历史读取都要按约定校验权限；文件URL也不能替代访问授权。</p>',15)),r(a,{source:""}),e[1]||(e[1]=i("h2",{id:"离线补拉与重投递",tabindex:"-1"},[n("离线补拉与重投递 "),i("a",{class:"header-anchor",href:"#离线补拉与重投递","aria-label":'Permalink to "离线补拉与重投递"'},"​")],-1)),e[2]||(e[2]=i("p",null,"消息队列可驱动投递，但不能仅以“消费者取走”代表用户已收到。接收端按会话游标补拉，服务端可能在确认丢失后重发同一消息，客户端按消息ID去重；顺序保证应限定到会话，不能从多个队列推导全局顺序。多设备需要明确各设备游标与账号已读状态是否共享。",-1)),e[3]||(e[3]=i("p",null,"例如序号101已推送但确认丢失，重连后从100补拉会再次得到101；去重后界面只显示一次。若消息已经超过保留期，应返回游标失效或缺口提示，而不是伪装成没有新消息。",-1)),r(a,{source:"Zmxvd2NoYXJ0IFRECkFbIumHjei/nuW5tuWujOaIkOiupOivgSJdIC0tPiBCWyLmj5DkuqTkvJror53muLjmoIcgMTAwIl0gLS0+IENbIuivu+WPluWQjue7reaMgeS5hea2iOaBryJdIC0tPiBEWyLov5Tlm54gMTAxIOWPiuWQjue7rea2iOaBryJdIC0tPiBFWyLlrqLmiLfnq6/mjInmtojmga8gSUQg5Y676YeNIl0gLS0+IEZbIuabtOaWsOehruiupOa4uOaghyJdCg=="})])}const q=t(u,[["render",d]]);export{b as __pageData,q as default};
